import{_ as e,o as l,c as a,a2 as d}from"./chunks/framework.CHX4lV2z.js";const g=JSON.parse('{"title":"Host Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"hosts/compatibility.md","filePath":"hosts/compatibility.md","lastUpdated":1789811186000}'),s={name:"hosts/compatibility.md"};function i(o,t,n,r,c,f){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="host-compatibility" tabindex="-1">Host Compatibility <a class="header-anchor" href="#host-compatibility" aria-label="Permalink to &quot;Host Compatibility&quot;">​</a></h1><p>TokenPilot integrates with OpenClaw, Codex CLI, Claude Code, and DeepSeek Harness. Each integration has a different boundary, so capabilities and setup instructions are documented per host.</p><h2 id="supported-hosts" tabindex="-1">Supported Hosts <a class="header-anchor" href="#supported-hosts" aria-label="Permalink to &quot;Supported Hosts&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Integration</th><th style="text-align:left;">Adapter Location</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./openclaw">OpenClaw</a></td><td style="text-align:left;">Native plugin slot</td><td style="text-align:left;"><code>components/adapters/openclaw/</code></td></tr><tr><td style="text-align:left;"><a href="./codex">Codex CLI</a></td><td style="text-align:left;">Local proxy + hooks</td><td style="text-align:left;"><code>components/adapters/codex/</code></td></tr><tr><td style="text-align:left;"><a href="./claude-code">Claude Code</a></td><td style="text-align:left;">Local gateway + MCP</td><td style="text-align:left;"><code>components/adapters/claude-code/</code></td></tr><tr><td style="text-align:left;"><a href="./deepseek-harness">DeepSeek Harness</a></td><td style="text-align:left;">Native Cordis plugin + optional context eviction + session status</td><td style="text-align:left;"><code>components/adapters/deepseek-harness/</code></td></tr></tbody></table><p>DeepSeek Harness provides opt-in context eviction and the read-only <code>/tokenpilot-status</code> command. It uses Harness&#39;s own transport and compaction, with separate profile configuration. See the <a href="./deepseek-harness">DeepSeek Harness guide</a> for installation, required settings, and troubleshooting.</p><p>The matrix below distinguishes shared product interfaces from host-native capabilities. <code>—</code> means the listed TokenPilot interface is not provided by that adapter; it does not describe unrelated features of the host itself.</p><h2 id="tokenpilot-host-feature-matrix" tabindex="-1">TokenPilot Host Feature Matrix <a class="header-anchor" href="#tokenpilot-host-feature-matrix" aria-label="Permalink to &quot;TokenPilot Host Feature Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">OpenClaw</th><th style="text-align:left;">Codex</th><th style="text-align:left;">Claude Code</th><th style="text-align:left;">DeepSeek Harness</th></tr></thead><tbody><tr><td style="text-align:left;">Stable Prefix</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Context Reduction</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Automatic Context Eviction</td><td style="text-align:left;">✅</td><td style="text-align:left;">Opt-in response-chain rebase¹</td><td style="text-align:left;">—</td><td style="text-align:left;">Opt-in; estimator and durable state required</td></tr><tr><td style="text-align:left;">User-approved <a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a></td><td style="text-align:left;">Immediate canonical apply</td><td style="text-align:left;">Scheduled response-chain rebase</td><td style="text-align:left;">Scheduled request overlay</td><td style="text-align:left;">No public Cleaner entrypoint</td></tr><tr><td style="text-align:left;">Visual Inspector</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Session Reports (<code>report</code>)</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—; native status instead</td></tr><tr><td style="text-align:left;">Session Status</td><td style="text-align:left;"><code>/lightrsi status</code> or CLI</td><td style="text-align:left;"><code>lightrsi codex status</code></td><td style="text-align:left;"><code>lightrsi claude-code status</code></td><td style="text-align:left;"><code>/tokenpilot-status</code>²</td></tr><tr><td style="text-align:left;">Shared Standalone CLI</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—; Harness plugin interface</td></tr><tr><td style="text-align:left;">MCP Recovery Server</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><code>mode conservative</code></td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—; profile configuration</td></tr><tr><td style="text-align:left;"><code>mode normal</code></td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td><td style="text-align:left;">—; profile configuration</td></tr><tr><td style="text-align:left;"><code>mode aggressive</code></td><td style="text-align:left;">✅</td><td style="text-align:left;">—</td><td style="text-align:left;">—</td><td style="text-align:left;">—; profile configuration</td></tr><tr><td style="text-align:left;">Proxy / Gateway Startup</td><td style="text-align:left;">Gateway restart</td><td style="text-align:left;">SessionStart hook</td><td style="text-align:left;">SessionStart hook</td><td style="text-align:left;">Not needed; Harness owns transport</td></tr></tbody></table><p>¹ The <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/codex/README.md#task-state-estimator-bridge-pr-b" target="_blank" rel="noreferrer">Codex adapter README</a> documents opt-in automatic eviction with both <code>taskStateEstimator.enabled</code> and <code>contextRewrite.enabled</code>. This does not provide the OpenClaw <code>eviction</code> commands or <code>aggressive</code> mode.</p><p>² DeepSeek Harness registers its status command when the profile provides command and session projection services. Its eviction pass runs before native Harness compaction by default. See <a href="/LightRSI/hosts/deepseek-harness">DeepSeek Harness</a> for configuration and status interpretation.</p>',10)])])}const x=e(s,[["render",i]]);export{g as __pageData,x as default};
